const text = input.response || input.text || '';
const issues = text.split('\n').map(l => l.trim()).filter(l => l.toUpperCase().startsWith('ISSUE:'));
const deductionPerIssue = 15;
const score = Math.max(0, 100 - issues.length * deductionPerIssue);
return { ...input, score, issues, issueCount: issues.length };

const fixList = input.response || input.text || input.content || "";
return {
  ...input,
  fixList,
  score: input.score,
  issueCount: input.issueCount,
  businessName: input.businessName,
  contactEmail: input.contactEmail,
  whatsappNumber: input.whatsappNumber
};
